                    ModelDb.Card<KarenWakeUpPromisePileOption>(),
                    ModelDb.Card<KarenWakeUpDiscardPileOption>()
                    ]);
                }
            }
        }
        else
        {
            await CardPileCmdEx.SelectFromDrawPileToHand(choiceContext, Owner, 2, NKarenWakeUpCardVfx.Observe);
